bruteForceSolution.code:
function patternLetterTriangle(n) {
  let rows = [];
  for (let i = 0; i < n; i++) {
    let row = '';
    for (let j = 0; j <= i; j++) {
      row += String.fromCharCode(65 + j);
    }
    rows.push(row);
  }
  return rows.join('\n');
}

